"text","text":", "},{"type":"variable","attrs":{"path":"workspace.name"}}]}]},"label":"Prepared by","meta":"prepared_by"},{"id":"date","kind":"extra","align":"left","content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"variable","attrs":{"path":"proposal.date"}}]}]},"label":"Date","meta":"date"},{"id":"validity","kind":"extra","align":"left","content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"variable","attrs":{"path":"proposal.valid_until"}}]}]},"meta":"valid_until","label":"Valid until"}],"layout":"editorial","logo_height":26,"background":{"type":"plain","graphic":"auto"}},"content":[{"type":"page_break","id":"93ebbd6d-0748-4dcc-8bf1-772e9b6d103d"},{"type":"heading","level":1,"text":"Overview","id":"21b2fc58-75e3-49d7-8dde-dfc251c8033c"},{"type":"paragraph","content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hi "},{"type":"variable","attrs":{"path":"client.first_name"}},{"type":"text","text":", [two or three sentences on where "},{"type":"variable","attrs":{"path":"client.company"}},{"type":"text","text":"'s social media is today and what they want from it, in their words]."}]}]},"id":"4f7d8d02-6771-4dbe-85d9-b5ae47c4de62"},{"type":"paragraph","content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"This proposal covers monthly social media management on [Facebook and Instagram]: we plan, create and post the content, look after comments and messages, and report on what's working."}]}]},"id":"c7e29fc3-24eb-4181-8c5f-74776a14ade3"},{"type":"heading","level":1,"text":"Goals","id":"1e0aa086-4222-4a83-8c51-b14a1a9088fd"},{"type":"paragraph","content":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Post consistently, so "},{"type":"variable","attrs":{"path":"client.company"}},{"type":"text","text":" stays visible to the people who already follow you"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Grow a local audience that turns into [calls, bookings, visits or sales]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Answer comments and messages quickly, so no customer question goes unanswered"}]}]}]}]},"id":"b8f924b4-f12c-48cd-8d11-5f516fc8bc2e"},{"type":"heading","level":1,"text":"What's included every month","id":"8d7b5fbc-b694-43ea-8fa0-f626e8c67653"},{"type":"paragraph","content":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A monthly content calendar, sent for your approval before anything is posted"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Designed graphics, captions and hashtags for every post"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Scheduling and posting at the times your audience is most active"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Replies to comments and messages on business days"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A monthly report: reach, engagement and follower growth, with what we'll try next"}]}]}]}]},"id":"2697d183-896f-4f27-8ce9-d93d6a0bb8f1"},{"type":"paragraph","content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Not included unless added: paid ads and ad spend, video shoots, influencer outreach, and platforms not listed above."}]}]},"id":"bea0aef4-3aaa-4d6a-8bbf-b99aafbe2819"},{"type":"heading","level":1,"text":"Choosing a plan","id":"e6823551-99f7-49d3-89d0-f4923ec1b287"},{"type":"paragraph","content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The plans differ by how often we post. [One sentence recommending a plan for this client and why.]"}]}]},"id":"9c2eb327-2aff-4737-859c-71cc07d851ef"},{"type":"paragraph","content":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Starter: 8 posts a month, about 2 a week"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Growth: 12 posts a month, about 3 a week"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pro: 18 posts a month, about 4–5 a week"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Premium: 24 posts a month, close to daily"}]}]}]}]},"id":"039f9280-37a9-4a66-86d5-d80863d790ca"},{"type":"paragraph","content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Add-ons, added to any plan: LinkedIn [$200] a month, each additional platform [$200] a month, and short-form video (Reels) [$75–150] each."}]}]},"id":"eb4116e6-dde0-4672-8c33-f78dcb69c423"},{"type":"heading","level":1,"text":"What to expect","id":"c7a0211e-b94d-4b16-89e9-1f3b32c7615c"},{"type":"paragraph","content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Social media builds over time. Most accounts see steadier engagement after [two to three months] of consistent posting. Platforms change how they show posts, so we can't promise a number of followers or likes; we'll show you what's changing every month."}]}]},"id":"e8a4c9fc-3757-429a-820a-fe06e10de668"},{"type":"heading","level":1,"text":"What we need from you","id":"897c7570-456a-42b0-8a49-35be5e8e944e"},{"type":"paragraph","content":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Admin access to your [Facebook and Instagram] accounts"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Your logo, brand colours and any photos you'd like us to use"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Approval of each month's calendar within [3] business days. We only post what you've approved, so a late approval moves that month's posts later."}]}]}]}]},"id":"e11ab6eb-994e-4680-8f68-2c594add72e6"},{"type":"page_break","id":"28764f0d-a50a-494a-81d8-080d30a48250"},{"type":"heading","level":1,"text":"Why {{workspace.name}}","content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why "},{"type":"variable","attrs":{"path":"workspace.name"}}]}]},"rich_heading":true,"id":"2ab08535-4727-4ebc-8ef9-48875c046534"},{"type":"paragraph","content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"[Case study: a business like theirs, where they started, and a result with a number.]"}]}]},"id":"bbc3f981-83f9-4368-865f-1dd911b400ca"},{"type":"page_break","id":"6ad29a1b-c261-4349-8038-05ab3babbf37"},{"type":"heading","level":1,"text":"Investment","id":"5aadacb1-a23f-4b18-8222-aaf7098d5e00"},{"type":"pricing_table","id":"2d7f6958-6705-4a57-8358-43d50a14974e"},{"type":"paragraph","content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Billed monthly. Plans have a [3]-month minimum, then continue month to month until either of us cancels with 30 days' notice."}]}]},"id":"c5f93694-fc7c-4563-8d4f-8f38eba6a94d"},{"type":"heading","level":1,"text":"Next steps","id":"b370e6ed-8aee-4d75-8a8d-b361f3b53d6f"},{"type":"paragraph","content":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Choose a plan and sign below."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"You'll get a secure link to set up monthly billing."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"We'll book a kickoff call, get access to your accounts, and send your first content calendar."}]}]