e. Fees already paid aren't refunded.","show_when":null},{"id":"terms-10","heading":"9. Governing law","body":"This agreement is governed by the laws of the State of {{workspace.state}}.","show_when":null},{"id":"terms-11","heading":"10. Entire agreement","body":"This signed proposal is the whole agreement between us about this work and replaces earlier discussions.","show_when":null}],"id":"6af0bce6-ecb8-4607-846f-333ce71b0b69"},{"type":"page_break","id":"9edf80f4-62a1-4a8d-86c8-dc128e3c1150"},{"type":"heading","text":"Signatures","level":1,"id":"7a27a781-cc0a-4e87-8a87-e318a88ded51"},{"type":"signature_block","role":"client","id":"31c2afdc-43eb-40e7-84dd-8ba7ef975708"},{"type":"signature_block","role":"company","id":"a8811c13-9842-43a7-8d4c-726b1048b9be"}],"default_quote":[],"default_items":[]}]$starter$::jsonb
