  ;
  skus text[] := array['social-starter-595','social-growth-995','social-pro-1650','social-premium-2200'];
  product jsonb; wanted_sku text; quote jsonb := '[]'; sublines jsonb; line jsonb;
  n integer := 0; matches integer; issues boolean := false;
  h text; quote_id uuid; group_id uuid; added integer;
begin
  if not exists(select 1 from public.workspaces where id=ws) then
    raise notice 'MarketFresh workspace not present; existing-workspace insert skipped.';
    return;
  end if;
  if exists(select 1 from public.templates where workspace_id=ws and data->>'starter_key'='social-media-management') then
    raise notice 'Social media management already exists; saved template kept unchanged.';
    return;
  end if;
  h := md5((t->>'id') || ':choices');
  group_id := (substr(h,1,8)||'-'||substr(h,9,4)||'-4'||substr(h,14,3)||'-8'||substr(h,18,3)||'-'||substr(h,21,12))::uuid;
  foreach wanted_sku in array skus loop
    select count(*) into matches from public.pricing_items where workspace_id=ws and data->>'sku'=wanted_sku;
    select data into product from public.pricing_items where workspace_id=ws and data->>'sku'=wanted_sku order by id limit 1;
    if matches<>1 or coalesce((product->>'active')::boolean,false)=false or coalesce((product->>'legacy')::boolean,false) then
      issues := true;
      raise notice 'Social quote left empty: SKU % is missing, duplicated, inactive or legacy.', wanted_sku;
    else
      h := md5((t->>'id') || ':quote-' || n::text);
      quote_id := (substr(h,1,8)||'-'||substr(h,9,4)||'-4'||substr(h,14,3)||'-8'||substr(h,18,3)||'-'||substr(h,21,12))::uuid;
      sublines := '[]';
      if jsonb_array_length(coalesce(nullif(product->'sublines','null'::jsonb),'[]'))>0 then
        for line in select value from jsonb_array_elements(product->'sublines') loop
          sublines := sublines || jsonb_build_array(line || jsonb_build_object(
            'list_amount',line->'amount','stripe_lookup_key',line->'stripe_lookup_key','qbo_item_ref',line->'qbo_item_ref'));
        end loop;
      else
        sublines := jsonb_build_array(jsonb_build_object('id',quote_id,'amount',product->'amount','list_amount',product->'amount',
          'interval',product->'interval','qty',1,'stripe_lookup_key',product->'stripe_lookup_key','qbo_item_ref',product->'qbo_item_ref'));
      end if;
      quote := quote || jsonb_build_array(jsonb_build_object('id',quote_id,'order',n,
        'name',coalesce(nullif(btrim(product->>'display_name'),''),product->>'name'),'description',coalesce(product->>'description',''),
        'source','catalog','pricing_item_id',product->'id','custom_family_id',null,'sublines',sublines,
        'optional',true,'default_selected',n=1,'selected',n=1,'choice_group_id',group_id,
        'min_term_months',product->'min_term_months','schedule',product->'schedule','plan_terms',product->'plan_terms'));
      raise notice 'Social quote SKU % resolved to %; amounts copied from catalog.',wanted_sku,product->>'id';
    end if;
    n := n+1;
  end loop;
  if issues then quote := '[]';end if;
  t := t || jsonb_build_object('default_items',quote);
  added := public.provision_starter_templates(ws,jsonb_build_array(t),false);
  raise notice 'Added % Social media management starter; % default quote items.',added,jsonb_array_length(quote);
end $$;
commit;
